def set_rules(world: "World") -> None:
    """Set access rules for all locations and entrances."""
    player = world.player
    multiworld = world.multiworld

    # Entrance rules
    multiworld.get_entrance("Garden Of Assemblage -> Space Paranoids", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_sp_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Port Royal", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_pr_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Twilight Town", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_tt_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Olympus Coliseum", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_oc_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Holloween Town", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_ht_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Land of Dragons", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_lod_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Beast's Castle", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_bc_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Agrabah", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_ag_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Pride Lands", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_pl_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Hollow Bastion", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_hb_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Disney Castle", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_dc_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Simulated Twilight Town", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_stt_unlocked(state, player, 1)

    multiworld.get_entrance("Garden Of Assemblage -> Levels Region (1 Visit Locking Item)", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_level_locking_unlock(state, player, 1)

    world.set_rule(
        multiworld.get_entrance("Garden Of Assemblage -> Final Form", player),
        (CanReachLocation("(BC2) Xaldin Bonus: Sora Slot 1")) | (CanReachLocation("(LoD2) Storm Rider Bonus: Sora Slot 1")) | (CanReachLocation("(PR2) Grim Reaper 2 Bonus: Sora Slot 1")) | (CanReachLocation("(TT3) Underground Concourse Mythril Gem")) | (CanReachLocation("Roxas Event Location"))
    )

    multiworld.get_entrance("Land of Dragons -> Shan Yu", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_shan_yu_rules(state, player)

    multiworld.get_entrance("Shan Yu -> Land of Dragons 2", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_lod_unlocked(state, player, 2)

    multiworld.get_entrance("Land of Dragons 2 -> Ansem Riku", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_ansem_riku_rules(state, player)

    multiworld.get_entrance("Ansem Riku -> Storm Rider", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_storm_rider_rules(state, player)

    multiworld.get_entrance("Storm Rider -> Data Xigbar", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_data_xigbar_rules(state, player)

    multiworld.get_entrance("Agrabah -> Twin Lords", player).access_rule = \
        lambda state: (_kingdomhearts2worldgen_get_blizzard_lord_rules(state, player)) and (_kingdomhearts2worldgen_get_fire_lord_rules(state, player))

    multiworld.get_entrance("Twin Lords -> Agrabah 2", player).access_rule = \
        lambda state: (_kingdomhearts2worldgen_ag_unlocked(state, player, 2)) and (_kingdomhearts2worldgen_kh2_has_all(state, player, ['Fire Element', 'Blizzard Element', 'Thunder Element']))

    multiworld.get_entrance("Agrabah 2 -> Genie Jafar", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_genie_jafar_rules(state, player)

    multiworld.get_entrance("Genie Jafar -> Data Lexaeus", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_data_lexaeus_rules(state, player)

    multiworld.get_entrance("Disney Castle -> Timeless River", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_dc_unlocked(state, player, 2)

    multiworld.get_entrance("Old Pete -> Future Pete", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_future_pete_rules(state, player)

    multiworld.get_entrance("Future Pete -> Terra", player).access_rule = \
        lambda state: (_kingdomhearts2worldgen_get_terra_rules(state, player)) and (state.has('Proof of Connection', player))

    multiworld.get_entrance("Future Pete -> Data Marluxia", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_data_marluxia_rules(state, player)

    multiworld.get_entrance("Pooh's House -> Piglet's House", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_hundred_acre_unlocked(state, player, 1)

    multiworld.get_entrance("Piglet's House -> Rabbit's House", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_hundred_acre_unlocked(state, player, 2)

    multiworld.get_entrance("Rabbit's House -> Roo's House", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_hundred_acre_unlocked(state, player, 3)

    multiworld.get_entrance("Roo's House -> Spooky Cave", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_hundred_acre_unlocked(state, player, 4)

    multiworld.get_entrance("Spooky Cave -> Starry Hill", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_hundred_acre_unlocked(state, player, 5)

    multiworld.get_entrance("Port Royal -> Barbosa", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_barbosa_rules(state, player)

    multiworld.get_entrance("Barbosa -> Port Royal 2", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_pr_unlocked(state, player, 2)

    multiworld.get_entrance("Grim Reaper 1 -> Grim Reaper 2", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_grim_reaper2_rules(state, player)

    multiworld.get_entrance("Grim Reaper 2 -> Data Luxord", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_data_luxord_rules(state, player)

    multiworld.get_entrance("Olympus Coliseum -> Cerberus", player).access_rule = \
        lambda state: _kingdomhearts2worldgen_get_cerberus_rules(state, player)

